  function icon(name, cls) {
    if (!name) return '';
    const key = String(name);
    const svg = ICONS[key] || ICONS[key.toLowerCase()] || '';
    if (!svg) return '';
    if (!cls) return svg;
    return svg.replace('class="ipk"', 'class="ipk ' + cls + '"');
  }

  function iconHtml(name, cls) {
    return icon(name, cls);
  }

  /** icon + plain text (caller must escape text if needed) */
  function label(name, text, cls) {
    const i = iconHtml(name, cls || 'ipk-xs');
    const t = text == null ? '' : String(text);
    return (i ? i + ' ' : '') + t;
  }

  const api = { ICONS, icon, iconHtml, label, keys: Object.keys(ICONS) };
  root.IconParkUI = api;
  root.L = root.L || {};
  root.L.icons = api;
